  2	 * La ruta que el usuario pasa en `--messaging-socket-path`. Porte de `G1o` de
  3	 * 2.1.283 (`chunk-yg53q7yp.js`).
  4	 *
  5	 * A diferencia de la ruta automática, no hay respaldo: la ruta es la que el
  6	 * usuario pidió, y cada rechazo es un `CliUserError` que dice qué corregir.
  7	 * El directorio tiene que ser suyo, real y privado; si no existe, se crea con
  8	 * modo 0700, sin atravesar un ancestro de otro usuario.
  9	 */
 10	import type { Stats } from 'node:fs'
 11	import { lstat, mkdir } from 'node:fs/promises'
 12	import { basename, dirname, isAbsolute, normalize } from 'node:path'
 13	
 14	import { CliUserError, getErrnoCode, isENOENT } from '../errorHelpers.ts'
 15	import { MAX_SOCKET_PATH_BYTES, isUsableLocalSocketAddress } from './socketPath.ts'
 16	
 17	export type ExplicitSocketPathDeps = { getuid: () => number | undefined }
 18	
 19	const PRIVATE_DIR_MODE = 0o700
 20	const GROUP_OR_OTHER_BITS = 0o077
 21	const PRIVATE_DIR_ADVICE = 'Use a private directory you own that only you use, e.g. mkdir -m 700 <dir> (or chmod 700 an existing one).'
 22	const UNUSABLE_DIR_ERRNOS = new Set(['ENOTDIR', 'EACCES', 'ELOOP', 'ENAMETOOLONG'])
 23	
 24	function checkShape(path: string): string {
 25	  if (!isAbsolute(path)) {
 26	    throw new CliUserError(path === ''
 27	      ? '--messaging-socket-path was given an empty value (an unset shell variable?). Pass an absolute socket path.'
 28	      : `--messaging-socket-path must be an absolute path, got: ${path}`)
 29	  }
 30	  if (path.split('/').includes('..')) throw new CliUserError(`--messaging-socket-path must not contain '..' segments, got: ${path}`)
 31	  const last = path.split('/').at(-1)
 32	  if (last === '' || last === '.') throw new CliUserError(`--messaging-socket-path must name a socket file inside a directory, got: ${path}`)
 33	  const normalized = normalize(path).replace(/\/+$/, '')
 34	  if (normalized === '' || !normalized.startsWith('/') || basename(normalized) === '') {
 35	    throw new CliUserError(`--messaging-socket-path must name a socket file inside a directory, got: ${path}`)
 36	  }
 37	  if (!isUsableLocalSocketAddress(normalized) || !isUsableLocalSocketAddress(path)) {
 38	    throw new CliUserError(`--messaging-socket-path must be a local socket path, got: ${path}`)
 39	  }
 40	  const bytes = Buffer.byteLength(normalized)
 41	  if (bytes > MAX_SOCKET_PATH_BYTES) {
 42	    throw new CliUserError(`--messaging-socket-path is too long for a Unix socket (${bytes} bytes, max ${MAX_SOCKET_PATH_BYTES}): ${normalized}. Choose a shorter path, e.g. under $XDG_RUNTIME_DIR or /tmp/<private-dir>.`)
 43	  }
 44	  return normalized
 45	}
 46	
 47	/** `G1o`: valida la ruta explícita y deja su directorio creado y privado; devuelve la ruta normalizada. */
 48	export async function validateExplicitSocketPath(path: string, deps: ExplicitSocketPathDeps = { getuid: () => process.getuid?.() }): Promise<string> {
 49	  const normalized = checkShape(path)
 50	  const dir = dirname(normalized)
 51	  const uid = deps.getuid()
 52	  const checkDir = (stats: Stats) => {
 53	    if (stats.isSymbolicLink()) throw new CliUserError(`--messaging-socket-path directory must be a real directory, not a symlink: ${dir}. ${PRIVATE_DIR_ADVICE}`)
 54	    if (!stats.isDirectory()) throw new CliUserError(`--messaging-socket-path parent is not a directory: ${dir}.`)
 55	    if (uid !== undefined && stats.uid !== uid) throw new CliUserError(`--messaging-socket-path directory ${dir} is not owned by you (uid ${stats.uid}). ${PRIVATE_DIR_ADVICE}`)
 56	    if ((stats.mode & GROUP_OR_OTHER_BITS) !== 0) {
 57	      throw new CliUserError(`--messaging-socket-path directory ${dir} is not private (mode ${(stats.mode & 0o7777).toString(8)}); the socket directory must be mode 0700 so no other user or group can reach or replace the socket. ${PRIVATE_DIR_ADVICE}`)
 58	    }
 59	  }
 60	  const statDir = async (): Promise<Stats | undefined> => {
 61	    try {
 62	      return await lstat(dir)
 63	    } catch (error) {
 64	      const code = getErrnoCode(error)
 65	      if (isENOENT(error)) return undefined
 66	      if (code !== undefined && UNUSABLE_DIR_ERRNOS.has(code)) {
 67	        throw new CliUserError(`--messaging-socket-path directory is not usable: ${dir} (${code}). Fix the path or its permissions, or choose another path. ${PRIVATE_DIR_ADVICE}`)
 68	      }
 69	      throw new CliUserError(`--messaging-socket-path directory could not be examined: ${dir} (${code ?? String(error)}). ${PRIVATE_DIR_ADVICE}`)
 70	    }
 71	  }
 72	  const existing = await statDir()
 73	  if (existing !== undefined) {
 74	    checkDir(existing)
 75	    return normalized
 76	  }
 77	  const missingAncestors: string[] = []
 78	  for (let ancestor = dirname(dir); ; ancestor = dirname(ancestor)) {
 79	    let stats: Stats | undefined
 80	    try {
 81	      stats = await lstat(ancestor)
 82	    } catch (error) {
 83	      if (!isENOENT(error)) throw new CliUserError(`--messaging-socket-path: cannot inspect ${ancestor} (${getErrnoCode(error) ?? String(error)}). ${PRIVATE_DIR_ADVICE}`)
 84	      missingAncestors.unshift(ancestor)
 85	    }
 86	    if (stats !== undefined) {
 87	      if (uid !== undefined && stats.uid !== uid && stats.uid !== 0) {
 88	        const kind = stats.isSymbolicLink() ? 'is a symlink' : 'is a directory'
 89	        const how = stats.isSymbolicLink() ? 'through' : 'inside'
 90	        throw new CliUserError(`--messaging-socket-path: ${ancestor} ${kind} owned by another user — refusing to create your sockets directory ${how} it. ${PRIVATE_DIR_ADVICE}`)
 91	      }
 92	      break
 93	    }
 94	    if (dirname(ancestor) === ancestor) break
 95	  }
 96	  try {
 97	    for (const ancestor of missingAncestors) {
 98	      try {
 99	        await mkdir(ancestor, { mode: PRIVATE_DIR_MODE })
100	      } catch (error) {
101	        if (getErrnoCode(error) !== 'EEXIST') throw error
102	        const raced = await lstat(ancestor)
103	        if (!raced.isDirectory() || (uid !== undefined && raced.uid !== uid)) {
104	          throw new CliUserError(`--messaging-socket-path: ${ancestor} appeared while your sockets directory was being created and is not a directory you own — refusing to use it. ${PRIVATE_DIR_ADVICE}`)
105	        }
106	      }
107	    }
108	    try {
109	      await mkdir(dir, { mode: PRIVATE_DIR_MODE })
110	    } catch (error) {
111	      if (getErrnoCode(error) !== 'EEXIST') throw error
112	    }
113	  } catch (error) {
114	    if (error instanceof CliUserError) throw error
115	    throw new CliUserError(`--messaging-socket-path directory ${dir} does not exist and could not be created (${getErrnoCode(error) ?? String(error)}). ${PRIVATE_DIR_ADVICE}`)
116	  }
117	  const created = await statDir()
118	  if (created === undefined) throw new CliUserError(`--messaging-socket-path directory ${dir} vanished while being set up. ${PRIVATE_DIR_ADVICE}`)
119	  checkDir(created)
120	  return normalized
121	}

