  1	/**
  2	 * Puerto de `ccnmt: packages/local-observability/src/errorHelpers.ts` (201
  3	 * líneas fuente, 100 % portado). Helpers de error compartidos, canónicos
  4	 * en todo el árbol ccnmt — la fuente declara "Zero dependencies besides
  5	 * the Anthropic SDK", y este puerto conserva esa propiedad: la única
  6	 * dependencia externa es `@anthropic-ai/sdk` (instalada como dependencia
  7	 * real de este paquete).
  8	 *
  9	 * Es el módulo con más líneas de importación entre los futuros
 10	 * consumidores (`memory`/`swarm`/`mcp-runtime`/…) medidos en el censo del
 11	 * porte — 71 líneas citan `errorHelpers.js`.
 12	 */
 13	
 14	import { APIUserAbortError } from '@anthropic-ai/sdk'
 15	
 16	export class ClaudeError extends Error {
 17	  constructor(message: string) {
 18	    super(message)
 19	    this.name = this.constructor.name
 20	  }
 21	}
 22	
 23	export class MalformedCommandError extends Error {}
 24	
 25	/** `_m`: un error que el usuario provocó con lo que pasó en la línea de comandos; se muestra tal cual. */
 26	export class CliUserError extends Error {
 27	  override name = 'CliUserError'
 28	}
 29	
 30	export class AbortError extends Error {
 31	  constructor(message?: string) {
 32	    super(message)
 33	    this.name = 'AbortError'
 34	  }
 35	}
 36	
 37	/**
 38	 * `true` sólo si `e` tiene alguna de las formas de "abort" que el árbol
 39	 * produce: nuestra clase `AbortError`, un `DOMException` de
 40	 * `AbortController.abort()` (`.name === 'AbortError'`), o el
 41	 * `APIUserAbortError` del SDK. La clase del SDK se verifica con
 42	 * `instanceof` porque los builds minificados mutilan los nombres de clase
 43	 * — `constructor.name` termina como algo tipo `nJT`, y el SDK nunca fija
 44	 * `this.name`, así que comparar por cadena falla en silencio en
 45	 * producción.
 46	 */
 47	export function isAbortError(e: unknown): boolean {
 48	  return (
 49	    e instanceof AbortError ||
 50	    e instanceof APIUserAbortError ||
 51	    (e instanceof Error && e.name === 'AbortError')
 52	  )
 53	}
 54	
 55	/**
 56	 * Error de parseo de un archivo de configuración — incluye la ruta del
 57	 * archivo y la configuración por defecto que debería usarse.
 58	 */
 59	export class ConfigParseError extends Error {
 60	  filePath: string
 61	  defaultConfig: unknown
 62	
 63	  constructor(message: string, filePath: string, defaultConfig: unknown) {
 64	    super(message)
 65	    this.name = 'ConfigParseError'
 66	    this.filePath = filePath
 67	    this.defaultConfig = defaultConfig
 68	  }
 69	}
 70	
 71	export class ShellError extends Error {
 72	  constructor(
 73	    public readonly stdout: string,
 74	    public readonly stderr: string,
 75	    public readonly code: number,
 76	    public readonly interrupted: boolean,
 77	  ) {
 78	    super('Shell command failed')
 79	    this.name = 'ShellError'
 80	  }
 81	}
 82	
 83	export class TeleportOperationError extends Error {
 84	  constructor(
 85	    message: string,
 86	    public readonly formattedMessage: string,
 87	  ) {
 88	    super(message)
 89	    this.name = 'TeleportOperationError'
 90	  }
 91	}
 92	
 93	/**
 94	 * Error cuyo mensaje es seguro de loguear a telemetría. El nombre largo
 95	 * exige confirmar explícitamente que el mensaje no contiene datos
 96	 * sensibles (rutas de archivo, URLs, fragmentos de código) antes de
 97	 * usarlo.
 98	 */
 99	export class TelemetrySafeError_I_VERIFIED_THIS_IS_NOT_CODE_OR_FILEPATHS extends Error {
100	  readonly telemetryMessage: string
101	
102	  constructor(message: string, telemetryMessage?: string) {
103	    super(message)
104	    this.name = 'TelemetrySafeError'
105	    this.telemetryMessage = telemetryMessage ?? message
106	  }
107	}
108	
109	export function hasExactErrorMessage(error: unknown, message: string): boolean {
110	  return error instanceof Error && error.message === message
111	}
112	
113	/** Normaliza un valor desconocido a `Error`. */
114	export function toError(e: unknown): Error {
115	  return e instanceof Error ? e : new Error(String(e))
116	}
117	
118	/** Extrae un mensaje de cadena de un valor tipo-error desconocido. */
119	export function errorMessage(e: unknown): string {
120	  return e instanceof Error ? e.message : String(e)
121	}
122	
123	/** Extrae el código errno (p. ej. `'ENOENT'`, `'EACCES'`) de un error capturado. */
124	export function getErrnoCode(e: unknown): string | undefined {
125	  if (e && typeof e === 'object' && 'code' in e && typeof e.code === 'string') {
126	    return e.code
127	  }
128	  return undefined
129	}
130	
131	/** `true` si el error es ENOENT (el archivo o directorio no existe). */
132	export function isENOENT(e: unknown): boolean {
133	  return getErrnoCode(e) === 'ENOENT'
134	}
135	
136	/**
137	 * Extrae la ruta errno (la ruta del filesystem que disparó el error) de
138	 * un error capturado. `undefined` si el error no trae ruta.
139	 */
140	export function getErrnoPath(e: unknown): string | undefined {
141	  if (e && typeof e === 'object' && 'path' in e && typeof e.path === 'string') {
142	    return e.path
143	  }
144	  return undefined
145	}
146	
147	/** Extrae el mensaje + los primeros N frames del stack de un error desconocido. */
148	export function shortErrorStack(e: unknown, maxFrames = 5): string {
149	  if (!(e instanceof Error)) return String(e)
150	  if (!e.stack) return e.message
151	  const lines = e.stack.split('\n')
152	  const header = lines[0] ?? e.message
153	  const frames = lines.slice(1).filter(l => l.trim().startsWith('at '))
154	  if (frames.length <= maxFrames) return e.stack
155	  return [header, ...frames.slice(0, maxFrames)].join('\n')
156	}
157	
