  1	/**
  2	 * El directorio donde viven los sockets de las sesiones: se verifica cada
  3	 * componente del camino antes de confiar en él y se crea privado. Porte de
  4	 * `Re`, `M`, `dn`, `V`, `Te`, `un`, `cn`, `fn`, `se`, `Ee`, `X`, `ke`, `ve`,
  5	 * `ln` y `De` de 2.1.283 (`chunk-yg53q7yp.js`).
  6	 *
  7	 * Un componente es aceptable si es nuestro, o de root, y además privado, o
  8	 * escribible por otros sólo con el sticky bit. Un directorio compartido
  9	 * permitiría a otro usuario sustituir el socket.
 10	 */
 11	import type { Stats } from 'node:fs'
 12	import { chmod, lstat, mkdir, readlink, realpath } from 'node:fs/promises'
 13	import { basename, dirname, isAbsolute, join } from 'node:path'
 14	
 15	import { getErrnoCode, isENOENT } from '../errorHelpers.ts'
 16	import { sanitizeForDisplay, shellQuote } from './displayText.ts'
 17	import { TRUSTED_SYSTEM_DIRS, probeUidNamespace, type UidNamespace } from './uidNamespace.ts'
 18	
 19	export const SOCKETS_DIR_VET_KINDS = [
 20	  'directory_rule', 'foreign_owner', 'leaf_shape', 'dangling_link', 'raced',
 21	  'not_directory', 'symlink_loop', 'uid_collapse', 'internal',
 22	] as const
 23	export type SocketsDirVetKind = (typeof SOCKETS_DIR_VET_KINDS)[number]
 24	
 25	export type RefusedComponent = { path: string; uid: number; gid: number; mode: number; ownerRefused?: boolean }
 26	
 27	export class SocketsDirError extends Error {
 28	  constructor(readonly kind: SocketsDirVetKind, message: string, readonly refusedComponent?: RefusedComponent) {
 29	    super(message)
 30	    this.name = 'SocketsDirError'
 31	  }
 32	}
 33	
 34	export type SocketsDirDeps = {
 35	  getuid: () => number | undefined
 36	  getgid: () => number | undefined
 37	  probeNamespace: () => Promise<UidNamespace | undefined>
 38	  env: Record<string, string | undefined>
 39	}
 40	
 41	export const processSocketsDirDeps: SocketsDirDeps = {
 42	  getuid: () => process.getuid?.(),
 43	  getgid: () => process.getgid?.(),
 44	  probeNamespace: () => probeUidNamespace(),
 45	  env: process.env,
 46	}
 47	
 48	const PRIVATE_DIR_MODE = 0o700
 49	const STICKY_BIT = 0o1000
 50	const WORLD_WRITABLE = 0o002
 51	const GROUP_WRITABLE = 0o020
 52	const MAX_SYMLINK_DEPTH = 16
 53	
 54	/** `V`: el componente rehusado, tal como se describe en el error. */
 55	function componentOf(path: string, stats: Stats, ownerRefused?: boolean): RefusedComponent {
 56	  return { path, uid: stats.uid, gid: stats.gid, mode: stats.mode & 0o7777, ...(ownerRefused !== undefined && { ownerRefused }) }
 57	}
 58	
 59	function danglingLink(): SocketsDirError {
 60	  return new SocketsDirError('dangling_link', 'a component of the sockets path is a symlink whose target does not exist — create the target (0700) or repoint the link')
 61	}
 62	
 63	/** `Re`: verifica el camino del directorio de sockets y lo deja creado con modo 0700. */
 64	export async function prepareSocketsDirectory(dir: string, deps: SocketsDirDeps = processSocketsDirDeps): Promise<void> {
 65	  if (!isAbsolute(dir)) throw new SocketsDirError('internal', 'sockets directory must be absolute here')
 66	  const uid = deps.getuid()
 67	  const gid = deps.getgid()
 68	  const namespace = await deps.probeNamespace()
 69	  if (namespace?.uidCollapses) {
 70	    throw new SocketsDirError('uid_collapse', 'this process reads as the kernel overflow uid (user namespace without a uid mapping) — ownership cannot be verified; refusing to use the sockets directory')
 71	  }
 72	  const ownedByUs = (owner: number) => owner === uid && !namespace?.uidCollapses
 73	  const checkLeaf = (stats: Stats) => {
 74	    if (stats.isSymbolicLink()) throw new SocketsDirError('leaf_shape', 'sockets directory is a symlink — refusing to use it', componentOf(dir, stats))
 75	    if (!stats.isDirectory()) throw new SocketsDirError('leaf_shape', 'sockets directory exists but is not a directory', componentOf(dir, stats))
 76	    if (uid !== undefined && !ownedByUs(stats.uid)) throw new SocketsDirError('foreign_owner', 'sockets directory is owned by another user — refusing to use it', componentOf(dir, stats))
 77	  }
 78	  /** El camino real de un componente, si sigue siendo el mismo inodo que se examinó. */
 79	  const verifiedRealPath = async (path: string, stats: Stats): Promise<string | undefined> => {
 80	    try {
 81	      const real = stats.isSymbolicLink() ? join(await realpath(dirname(path)), basename(path)) : await realpath(path)
 82	      const again = await lstat(real)
 83	      return again.dev === stats.dev && again.ino === stats.ino ? real : undefined
 84	    } catch {
 85	      return undefined
 86	    }
 87	  }
 88	  const ambiguousOwner = (owner: number) => namespace !== undefined
 89	    && ((namespace.unmappedOwnerUid !== undefined && owner === namespace.unmappedOwnerUid) || (owner === 0 && namespace.rootUidAmbiguous))
 90	  const isTrustedSystemDir = (real: string | undefined) => real !== undefined && TRUSTED_SYSTEM_DIRS.has(real)
 91	  const ownerAcceptable = (owner: number, isLeafToCreate: boolean, real: string | undefined) =>
 92	    uid === undefined || ownedByUs(owner) || (!isLeafToCreate && (ambiguousOwner(owner) ? isTrustedSystemDir(real) : owner === 0))
 93	  const directoryAcceptable = (stats: Stats, isLeafToCreate: boolean, real: string | undefined) => {
 94	    if (!ownerAcceptable(stats.uid, isLeafToCreate, real)) return false
 95	    if ((stats.mode & STICKY_BIT) !== 0) return true
 96	    if ((stats.mode & WORLD_WRITABLE) !== 0) return false
 97	    if ((stats.mode & GROUP_WRITABLE) !== 0) return ownedByUs(stats.uid) && gid !== undefined && stats.gid === gid && gid === uid
 98	    return true
 99	  }
100	  const termuxRoot = deps.env.TERMUX_VERSION && deps.env.PREFIX ? dirname(dirname(deps.env.PREFIX)) : undefined
101	  const isWalkRoot = (path: string) => dirname(path) === path || path === termuxRoot
102	
103	  type Walk = { startExists: boolean; deepestExisting: string | undefined; sawSymlink: boolean }
104	  const walkUp = async (start: string, isLeafToCreate: boolean, depth = 0): Promise<Walk> => {
105	    if (depth > MAX_SYMLINK_DEPTH) throw new SocketsDirError('symlink_loop', 'sockets-directory chain: too many levels of symlinks')
106	    let startExists = false
107	    let deepestExisting: string | undefined
108	    let sawSymlink = false
109	    for (let path = start, isStart = true; ; path = dirname(path), isStart = false) {
110	      let stats: Stats | undefined
111	      try {
112	        stats = await lstat(path)
113	      } catch (error) {
114	        if (!isENOENT(error)) throw error
115	      }
116	      if (stats !== undefined) {
117	        deepestExisting ??= path
118	        const leafToCreate = isStart && isLeafToCreate
119	        if (stats.isSymbolicLink()) {
120	          sawSymlink = true
121	          const real = ambiguousOwner(stats.uid) ? await verifiedRealPath(path, stats) : undefined
122	          if (!ownerAcceptable(stats.uid, false, real)) {
123	            throw new SocketsDirError('foreign_owner', 'a sockets-directory component is a symlink owned by another user — refusing to use it', componentOf(path, stats))
124	          }
125	          const raw = (await readlink(path)).replace(/\/{2,}/g, '/')
126	          const trimmed = raw.length > 1 && raw.endsWith('/') ? raw.slice(0, -1) : raw
127	          const target = isAbsolute(trimmed) ? trimmed : `${await realpath(dirname(path))}/${trimmed}`
128	          const inner = await walkUp(target, leafToCreate, depth + 1)
129	          if (isStart) startExists = inner.startExists
130	        } else {
131	          if (!stats.isDirectory()) {
132	            throw new SocketsDirError('not_directory', 'a sockets-directory component exists but is not a directory — refusing to use it', componentOf(path, stats))
133	          }
134	          const real = ambiguousOwner(stats.uid) ? await verifiedRealPath(path, stats) : undefined
135	          if (!directoryAcceptable(stats, leafToCreate, real)) {
136	            throw new SocketsDirError('directory_rule', 'a sockets-directory component is not a private-or-sticky directory owned by us or root — refusing to use it', componentOf(path, stats, !ownerAcceptable(stats.uid, leafToCreate, real)))
137	          }
138	          if (isStart) startExists = true
139	        }
140	      }
141	      if (isWalkRoot(path)) break
142	    }
143	    return { startExists, deepestExisting, sawSymlink }
144	  }
145	
146	  const parent = dirname(dir)
147	  const walk = await walkUp(parent, false)
148	  const parentMissing = !walk.startExists
149	  let leaf: Stats | undefined
150	  try {
151	    leaf = await lstat(dir)
152	  } catch (error) {
153	    if (!isENOENT(error)) throw error
154	  }
155	  if (parentMissing && walk.deepestExisting === parent) throw danglingLink()
156	  if (parentMissing) {
157	    const toCreate: string[] = []
158	    for (let path = parent; path !== walk.deepestExisting && !isWalkRoot(path); path = dirname(path)) toCreate.unshift(path)
159	    for (const path of toCreate) {
160	      try {
161	        await mkdir(path, { mode: PRIVATE_DIR_MODE })
162	      } catch (error) {
163	        if (isENOENT(error) && walk.sawSymlink) throw danglingLink()
164	        if (getErrnoCode(error) !== 'EEXIST') throw error
165	        const raced = await lstat(path)
166	        if (!raced.isDirectory() || (uid !== undefined && !ownedByUs(raced.uid))) {
167	          throw new SocketsDirError('raced', 'a sockets-directory component appeared while being created and is not our directory — refusing to use it')
168	        }
169	      }
170	    }
171	    if (!(await walkUp(parent, true)).startExists) throw new SocketsDirError('raced', 'sockets base directory vanished while being set up')
172	  }
173	  if (leaf === undefined) {
174	    try {
175	      await mkdir(dir, { mode: PRIVATE_DIR_MODE })
176	    } catch (error) {
177	      if (getErrnoCode(error) !== 'EEXIST') throw error
178	    }
179	    leaf = await lstat(dir)
180	  }
181	  checkLeaf(leaf)
182	  if ((leaf.mode & 0o777) !== PRIVATE_DIR_MODE) await chmod(dir, PRIVATE_DIR_MODE)
183	}
