185	/** `se`: la clase de rechazo de un error, si la tiene. */
186	export function vetKindOf(error: unknown): SocketsDirVetKind | undefined {
187	  return error instanceof SocketsDirError ? error.kind : undefined
188	}
189	
190	const FALLBACK_ERRNOS = new Set(['EACCES', 'EPERM', 'EROFS', 'ENOSPC', 'EDQUOT', 'ENOTDIR'])
191	
192	/** `fn`: si tras este rechazo vale la pena el respaldo por uid en `/tmp`. */
193	export function canFallBackToPerUid(error: unknown): boolean {
194	  switch (vetKindOf(error)) {
195	    case 'directory_rule': case 'foreign_owner': case 'leaf_shape': case 'not_directory':
196	      return true
197	    case 'dangling_link': case 'symlink_loop': case 'raced': case 'uid_collapse': case 'internal':
198	      return false
199	    case undefined:
200	      break
201	  }
202	  const code = getErrnoCode(error)
203	  return code !== undefined && FALLBACK_ERRNOS.has(code)
204	}
205	
206	const PRIVATE_DIR_ADVICE = 'Point XDG_RUNTIME_DIR or THYROX_CODE_TMPDIR at a private (0700) directory you own to use a different location.'
207	const NOT_DIRECTORY_HINT = `A component of the sockets path is not a directory (a regular file is in the way). ${PRIVATE_DIR_ADVICE}`
208	const SYMLINK_LOOP_HINT = `The sockets path runs through a symlink loop. ${PRIVATE_DIR_ADVICE}`
209	const UID_COLLAPSE_HINT = 'This process runs in a user namespace without a uid mapping (its own uid reads as the kernel overflow uid), so file ownership cannot be verified. Start it with a uid map (e.g. `unshare -Ur` / `--map-current-user`), or pass --messaging-socket-path.'
210	
211	/** `De`: qué puede hacer quien lee el rechazo. */
212	export function socketsDirHint(error: unknown): string {
213	  switch (vetKindOf(error)) {
214	    case 'directory_rule':
215	      return `A directory on the sockets path is shared (world- or group-writable without the sticky bit, e.g. a container volume mounted at /tmp) or not owned by you or root. ${PRIVATE_DIR_ADVICE}`
216	    case 'foreign_owner': case 'leaf_shape':
217	      return PRIVATE_DIR_ADVICE
218	    case 'not_directory':
219	      return NOT_DIRECTORY_HINT
220	    case 'symlink_loop':
221	      return SYMLINK_LOOP_HINT
222	    case 'uid_collapse':
223	      return UID_COLLAPSE_HINT
224	    case 'dangling_link': case 'raced': case 'internal':
225	      return ''
226	    case undefined:
227	      break
228	  }
229	  switch (getErrnoCode(error)) {
230	    case 'ENOTDIR': return NOT_DIRECTORY_HINT
231	    case 'ELOOP': return SYMLINK_LOOP_HINT
232	    case 'EACCES': case 'EPERM':
233	      return `This user lacks permission on part of the sockets path (an ancestor is not searchable, or the parent is not writable). ${PRIVATE_DIR_ADVICE}`
234	    case 'ENOENT': return `An ancestor of the sockets path does not exist. ${PRIVATE_DIR_ADVICE}`
235	    default: return ''
236	  }
237	}
