239	/** `un`: los caracteres que se pueden mostrar citados sin ambigüedad. */
240	const DISPLAY_SAFE_CHAR = /^[A-Za-z0-9._\/ ~+=:@,#%-]$/
241	
242	/** `Te`: el componente rehusado, con su dueño y modo, y la orden que lo arregla. */
243	export function refusedComponentDetail(error: unknown): string | undefined {
244	  if (vetKindOf(error) === 'uid_collapse') {
245	    return 'this process runs in a user namespace without a uid mapping, so file ownership cannot be verified — start it with a uid map (e.g. unshare -Ur), or pass --messaging-socket-path'
246	  }
247	  const component = error instanceof SocketsDirError ? error.refusedComponent : undefined
248	  if (component === undefined) return undefined
249	  const mode = component.mode.toString(8).padStart(4, '0')
250	  const owner = `(owner ${component.uid}:${component.gid}, mode ${mode})`
251	  const orPass = 'or pass --messaging-socket-path'
252	  const displayed = sanitizeForDisplay(component.path)
253	  let quotable = displayed === component.path
254	  const shown = `'${Array.from(displayed, char => {
255	    if (DISPLAY_SAFE_CHAR.test(char)) return char
256	    quotable = false
257	    return '?'
258	  }).join('')}'`
259	  const fix = (bits: 'o-w' | 'g-w', suffix: string) =>
260	    quotable ? `chmod ${bits} ${shellQuote([component.path])}${suffix}` : `clear its ${bits === 'o-w' ? 'other' : 'group'}-write bit${suffix}`
261	  const privateDir = `use a private directory (XDG_RUNTIME_DIR / THYROX_CODE_TMPDIR), ${orPass}`
262	  switch (vetKindOf(error)) {
263	    case 'directory_rule': {
264	      if (component.ownerRefused === true) return `${shown} is not owned by you or root ${owner} — ${privateDir}`
265	      const sticky = (component.mode & STICKY_BIT) !== 0
266	      if (!sticky && (component.mode & WORLD_WRITABLE) !== 0) return `${shown} is world-writable without the sticky bit ${owner} — ${fix('o-w', ' (or chmod +t)')}, ${orPass}`
267	      if (!sticky && (component.mode & GROUP_WRITABLE) !== 0) return `${shown} is group-writable without the sticky bit ${owner} — ${fix('g-w', '')}, ${orPass}`
268	      return `${shown} is not owned by you or root ${owner} — ${privateDir}`
269	    }
270	    case 'foreign_owner':
271	      return `${shown} is owned by another user ${owner} — ${privateDir}`
272	    case 'not_directory': case 'leaf_shape':
273	      return `${shown} is not a directory ${owner} — remove it or ${privateDir}`
274	    default:
275	      return undefined
276	  }
277	}

