  1	/**
  2	 * Una conexión entrante al buzón: la lee por líneas JSON, exige la línea de
  3	 * autenticación cuando el buzón la pide, cierra la conexión que calla o que
  4	 * excede el tope, y entrega cada mensaje al enrutado con la identidad del par.
  5	 *
  6	 * Porte de `en` (`chunk-yg53q7yp.js`) de 2.1.283, con `WOt`
  7	 * (`chunk-qcy58j4w.js`). El enrutado (`Qe`) y la decisión de confiar en la
  8	 * ancestría del par (`unr`) llegan como dependencias.
  9	 */
 10	import type { Socket } from 'node:net'
 11	
 12	import { logForDebugging } from '../debug.ts'
 13	import { reportFeatureBad, reportFeatureOk, reportFeatureSad } from './featureTelemetry.ts'
 14	import { isAuthFrame, matchInboxToken, type TokenOrigin } from './inboxAuth.ts'
 15	import type { InboxState } from './inboxState.ts'
 16	import { redactLogFragment, withholdTokenText } from './logRedaction.ts'
 17	import { parentPidChain, peerPid, readStartTokenSync } from './peerCredentials.ts'
 18	
 19	/** `WOt`: la línea más larga que el buzón acumula antes de cortar la conexión. */
 20	export const LINE_LIMIT_CHARS = 1048576
 21	const AUTH_FEATURE = 'cross_session_inbox_auth'
 22	
 23	/** Lo que se sabe del proceso que envió un mensaje. */
 24	export type PeerIdentity = {
 25	  pid: number | undefined
 26	  startToken: string | undefined
 27	  /** Sus padres, sólo cuando se confía en la ancestría; vacía si el par cambió desde que conectó. */
 28	  ancestry: number[] | undefined
 29	  origin: TokenOrigin | undefined
 30	}
 31	
 32	export interface InboxConnectionDeps {
 33	  state: InboxState
 34	  /** `Qe`: entrega un mensaje ya autenticado. */
 35	  route: (message: unknown, peer: PeerIdentity) => void
 36	  /** `unr`: si el modo de permisos permite confiar en la ancestría del par. */
 37	  trustsAncestry: () => boolean
 38	  ownPid: number
 39	  peerPid: (socket: Socket) => number | undefined
 40	  startTokenOf: (pid: number) => string | undefined
 41	  parentChain: (pid: number) => number[]
 42	  log: (message: string) => void
 43	  warn: (message: string) => void
 44	  telemetry: {
 45	    ok: (feature: string) => void
 46	    bad: (feature: string, code: string) => void
 47	    sad: (feature: string, code: string) => void
 48	  }
 49	}
 50	
 51	/** `le`: un objeto con un `type` de texto. */
 52	function hasMessageType(value: unknown): value is { type: string } {
 53	  return typeof value === 'object' && value !== null && 'type' in value && typeof (value as { type: unknown }).type === 'string'
 54	}
 55	
 56	export function processConnectionDeps(state: InboxState, route: InboxConnectionDeps['route'], trustsAncestry: () => boolean): InboxConnectionDeps {
 57	  return {
 58	    state,
 59	    route,
 60	    trustsAncestry,
 61	    ownPid: process.pid,
 62	    peerPid: socket => peerPid(socket),
 63	    startTokenOf: pid => readStartTokenSync(pid),
 64	    parentChain: pid => parentPidChain(pid),
 65	    log: message => logForDebugging(message),
 66	    warn: message => logForDebugging(message, { level: 'warn' }),
 67	    telemetry: {
 68	      ok: feature => reportFeatureOk(feature),
 69	      bad: (feature, code) => reportFeatureBad(feature, code),
 70	      sad: (feature, code) => reportFeatureSad(feature, code),
 71	    },
 72	  }
 73	}
 74	
 75	/** `en`: atiende una conexión aceptada por el servidor del buzón. */
 76	export function handleInboxConnection(socket: Socket, deps: InboxConnectionDeps): void {
 77	  const { state } = deps
 78	  socket.setEncoding('utf8')
 79	  const deadlineMs = state.firstLineDeadlineMs
 80	  let deadline: ReturnType<typeof setTimeout> | undefined = setTimeout(() => {
 81	    deadline = undefined
 82	    try {
 83	      deps.log(`[uds-messaging] Closing a connection that sent no complete line within ${deadlineMs} ms`)
 84	      if (!state.silentDropReported) {
 85	        state.silentDropReported = true
 86	        deps.telemetry.sad(AUTH_FEATURE, 'silent_connection_deadline')
 87	      }
 88	      socket.destroy()
 89	    } catch (error) {
 90	      deps.warn(`[uds-messaging] Failed to close a silent connection: ${error}`)
 91	    }
 92	  }, deadlineMs)
 93	  deadline.unref()
 94	  const disarmDeadline = () => {
 95	    if (deadline !== undefined) {
 96	      clearTimeout(deadline)
 97	      deadline = undefined
 98	    }
 99	  }
100	  socket.once('close', disarmDeadline)
101	  socket.once('error', disarmDeadline)
102	
103	  const trustsAncestry = deps.ownPid !== 1 && deps.trustsAncestry()
104	  let connectedPeer: { pid: number; token: string } | undefined
105	  if (trustsAncestry) {
106	    const pid = deps.peerPid(socket)
107	    const token = pid !== undefined ? deps.startTokenOf(pid) : undefined
108	    if (pid !== undefined && token !== undefined) connectedPeer = { pid, token }
109	  }
110	
111	  let identity: Omit<PeerIdentity, 'origin'> | undefined
112	  let origin: TokenOrigin | undefined
113	  let sawFirstLine = false
114	  let buffer = ''
115	
116	  const dropUnauthenticated = (what: string) => {
117	    deps.warn(`[uds-messaging] Dropped ${what} from a connection that did not authenticate; closing it`)
118	    if (!state.authDropReported) {
119	      state.authDropReported = true
120	      deps.telemetry.bad(AUTH_FEATURE, 'unauthed_drop')
121	    }
122	    socket.destroy()
123	  }
124	
125	  const resolveIdentity = (): Omit<PeerIdentity, 'origin'> => {
126	    const pid = deps.peerPid(socket)
127	    const startToken =
128	      pid === undefined ? undefined : connectedPeer !== undefined ? (connectedPeer.pid === pid ? connectedPeer.token : undefined) : deps.startTokenOf(pid)
129	    let ancestry: number[] | undefined
130	    if (pid !== undefined && trustsAncestry) {
131	      const unchanged = connectedPeer !== undefined && connectedPeer.pid === pid && deps.startTokenOf(pid) === connectedPeer.token
132	      ancestry = unchanged ? deps.parentChain(pid) : []
133	    }
134	    return { pid, startToken, ancestry }
135	  }
136	
137	  const handleMessage = (message: unknown) => {
